Now the question becomes, can we make it faster?
One optimization we can make is using an array instead of a vector in C++, this statically sized data structure is quite a bit faster to loop over.




::: {.cell}

```{.cpp .cell-code}
#include <cmath>
#include <Rcpp.h>
#include <vector>
using namespace Rcpp;

// [[Rcpp::export]]
int even_fibonaccis_arr(int n = 4000000) {
    std::array<int, 1000000> fibs;
    fibs[0] = 1;
    fibs[1] = 2;
    long long cur_sum = 2;
    for (int i = 2; i < fibs.size(); ++i) {
        fibs[i] = fibs[i - 1] + fibs[i - 2];
        if (fibs[i] > n) break;
         if (fibs[i] % 2 == 0) {
            cur_sum += fibs[i];
        }
    }
    return cur_sum;
}

```
